import React, { useState } from 'react';

const SimpleContactPage = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Formulaire soumis:', formData);
    alert('Merci pour votre message !');
    setFormData({ name: '', email: '', message: '' });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-white to-blue-50">
      <div className="container mx-auto px-4 py-20">
        <div className="max-w-4xl mx-auto">
          {/* En-tête */}
          <div className="text-center mb-16">
            <h1 className="text-5xl md:text-6xl font-bold text-gray-800 mb-6">
              Parlons de votre <span className="text-blue-600">projet</span>
            </h1>
            <p className="text-xl text-gray-600 max-w-2xl mx-auto">
              Discutons ensemble de vos idées et voyons comment nous pouvons vous aider.
            </p>
          </div>

          <div className="grid lg:grid-cols-2 gap-12">
            {/* Informations */}
            <div className="space-y-8">
              {[
                {
                  title: "Email direct",
                  content: "contact@entreprise.com",
                  color: "from-blue-500 to-blue-600"
                },
                {
                  title: "Téléphone",
                  content: "+33 1 23 45 67 89",
                  color: "from-emerald-500 to-emerald-600"
                },
                {
                  title: "Adresse",
                  content: "123 Rue de Paris, 75001",
                  color: "from-purple-500 to-purple-600"
                }
              ].map((item, index) => (
                <div 
                  key={index}
                  className="bg-white rounded-2xl p-8 shadow-lg hover:shadow-2xl transition-all duration-500"
                >
                  <div className={`bg-gradient-to-r ${item.color} w-3 h-12 rounded-full mb-4`}></div>
                  <h3 className="text-2xl font-bold text-gray-800 mb-2">{item.title}</h3>
                  <p className="text-gray-600 text-lg">{item.content}</p>
                </div>
              ))}
            </div>

            {/* Formulaire minimaliste */}
            <div className="bg-white rounded-2xl shadow-2xl p-10">
              <form onSubmit={handleSubmit} className="space-y-8">
                <div>
                  <input
                    type="text"
                    placeholder="Votre nom"
                    className="w-full px-6 py-4 text-lg border-b-2 border-gray-200 focus:border-blue-500 focus:outline-none transition-colors"
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                  />
                </div>

                <div>
                  <input
                    type="email"
                    placeholder="votre@email.com"
                    className="w-full px-6 py-4 text-lg border-b-2 border-gray-200 focus:border-blue-500 focus:outline-none transition-colors"
                    value={formData.email}
                    onChange={(e) => setFormData({...formData, email: e.target.value})}
                  />
                </div>

                <div>
                  <textarea
                    placeholder="Votre message..."
                    rows="5"
                    className="w-full px-6 py-4 text-lg border-b-2 border-gray-200 focus:border-blue-500 focus:outline-none transition-colors resize-none"
                    value={formData.message}
                    onChange={(e) => setFormData({...formData, message: e.target.value})}
                  />
                </div>

                <button
                  type="submit"
                  className="w-full bg-gradient-to-r from-blue-600 to-purple-600 text-white text-lg font-medium py-5 rounded-xl hover:shadow-2xl transform hover:-translate-y-1 transition-all duration-300"
                >
                  Envoyer le message →
                </button>
              </form>

              <div className="mt-10 pt-8 border-t border-gray-100 text-center">
                <p className="text-gray-500">
                  ⚡ Nous répondons généralement en moins de 2 heures
                </p>
              </div>
            </div>
          </div>

          {/* CTA */}
          <div className="mt-20 text-center">
            <div className="inline-block bg-gradient-to-r from-blue-500 to-purple-500 text-white px-8 py-4 rounded-full font-medium">
              📞 Appelez-nous directement : +33 6 12 34 56 78
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SimpleContactPage;
